mapper.update:
UPDATE TB_BBS_SURVEY
SET VIEW_CNT = VIEW_CNT + 1
WHERE SRVY_SN = #{srvySn}

mapper.select:
SELECT S.SRVY_SN AS srvySn, S.SRVY_TTL AS srvyTtl, S.SRVY_QITEM AS srvyQitem, S.CO_SN AS coSn, S.COHORT_SN AS cohortSn, S.USER_SN AS userSn, U.USER_NM AS userNm, S.SRVY_BGNG_DT AS srvyBgngDt, S.SRVY_END_DT AS srvyEndDt, S.SRVY_SCOPE AS srvyScope, S.BBS_TYPE AS bbsType, S.FORM_UUID AS formUuid, S.VIEW_CNT AS viewCnt, S.SRVY_DEL_YN AS delYn, S.SRVY_FRST_WRT_DT AS srvyFrstWrtDt, S.SRVY_LAST_MDFCN_DT AS srvyLastMdfcnDt FROM TB_BBS_SURVEY S JOIN TB_USER U ON S.USER_SN = U.USER_SN WHERE S.SRVY_DEL_YN = FALSE
AND S.CO_SN = #{coSn}
AND S.COHORT_SN = #{cohortSn}
AND S.BBS_TYPE = #{bbsType}
ORDER BY S.SRVY_FRST_WRT_DT DESC

mapper.update:
UPDATE TB_BBS_SURVEY
SET SRVY_DEL_YN = TRUE,
SRVY_LAST_MDFCN_DT = NOW()
WHERE SRVY_SN = #{srvySn}
AND USER_SN = #{userSn}
